( e => {
const { [ 'pt-br' ]: translations } = {"pt-br":{"dictionary":{"Copy selected content":"Copiar conteúdo selecionado","Paste content":"Colar conteúdo","Paste content as plain text":"Colar conteúdo como texto simples"}}};
e[ 'pt-br' ] ||= { dictionary: {}, getPluralForm: null };
e[ 'pt-br' ].dictionary = Object.assign( e[ 'pt-br' ].dictionary, translations.dictionary );
if ( translations.getPluralForm ) {
e[ 'pt-br' ].getPluralForm = translations.getPluralForm;
}
} )( window.CKEDITOR_TRANSLATIONS ||= {} );
